        //-------------------- Private Methods ----------------------

        private async Task LoadGridDataAsync()
        {
            try
            {
                await InvokeAsync(StateHasChanged);

                httpResult = await _equipmentClient.UsageListAsync();
                if (httpResult.IsSucceeded)
                {
                    UsageList = httpResult.Data.ToList() ?? [];
                }

                StateHasChanged();
            }
            catch (Exception ex)
            {
                ErrorState.SetError(ex);
            }
            finally
            {
                await InvokeAsync(StateHasChanged);
            }
        }

        public Task ShowModal() => selector.Show();
        public Task HideModal() => selector.Hide();

        private async Task OnFinalSelect()
        {
            if (OnSelectItems.HasDelegate)
            {
                var items = _usageSimpleList.GetSelectedItems();
                await OnSelectItems.InvokeAsync(items);
            }

            if (OnSelectDtos.HasDelegate)
            {
                var dtos = _usageSimpleList.GetSelectedDtos();
                await OnSelectDtos.InvokeAsync(dtos);
            }
        }
    }
